def count_chars(text):
    counts = {'vowels': 0, 'consonants': 0}
    vowels = 'aeiouAEIOU'
    for char in text:
        if char.isalpha():
            if char in vowels:
                counts['vowels'] += 1
            else:
                counts['consonants'] += 1
    return counts
print(count_chars('Computer'))
```
