nums = []
while True:
    ch = input("1:Append 2:Delete 3:Exit -> ")
    if ch == '1':
        nums.append(int(input("Enter val: ")))
    elif ch == '2':
        val = int(input("Enter val to del: "))
        if val in nums: nums.remove(val)
    elif ch == '3':
        break
print("Final list:", nums)
